  for (const role of ["roles/iap.tunnelResourceAccessor", "roles/compute.osLogin"]) {
    new gcp.projects.IAMMember(
      `substrate-ssh-${role.replace("roles/", "")}-${deployer}`,
      {
        project: projectId,
        role,
        member: deployer,
      },
      { dependsOn: iapApi },
    );
  }
}

